<?php
namespace App\Http\Controllers;
use App\Models\Employee;
use App\Models\Organization;
use App\Services\EmployeeAccess;
use Carbon\CarbonImmutable;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\ValidationException;
class DailyController extends Controller {
 private function member(Request $r,Organization $o,string $permission): void {abort_unless($r->user()->hasPermission($permission),403);abort_unless($o->users()->where('users.id',$r->user()->id)->exists(),403);}
 private function employee(Request $r,Organization $o,string $permission): Employee {$this->member($r,$o,$permission);return Employee::where('organization_id',$o->id)->where('user_id',$r->user()->id)->firstOrFail();}
 private function event(Organization $o,int $id,int $actor,string $action,?array $before,?array $after,?string $reason=null): void {DB::table('attendance_events')->insert(['organization_id'=>$o->id,'attendance_entry_id'=>$id,'actor_id'=>$actor,'action'=>$action,'before_values'=>$before?json_encode($before):null,'after_values'=>$after?json_encode($after):null,'reason'=>$reason,'created_at'=>now(),'updated_at'=>now()]);}
 public function mine(Request $r,Organization $organization) {$e=$this->employee($r,$organization,'attendance.self.view');$entries=DB::table('attendance_entries')->where('organization_id',$organization->id)->where('employee_id',$e->id)->orderByDesc('clock_in')->get();return view('attendance.mine',compact('organization','entries'));}
 public function clockIn(Request $r,Organization $organization) {
  $this->employee($r,$organization,'attendance.self.clock_in');
  DB::transaction(function()use($r,$organization){Organization::whereKey($organization->id)->lockForUpdate()->firstOrFail();$e=$this->employee($r,$organization,'attendance.self.clock_in');if($e->status!=='active') throw ValidationException::withMessages(['attendance'=>'Only active employees can clock in.']);if(DB::table('attendance_entries')->where('organization_id',$organization->id)->where('employee_id',$e->id)->whereNull('clock_out')->exists()) throw ValidationException::withMessages(['attendance'=>'You already have an open attendance entry.']);$time=now()->utc()->format('Y-m-d H:i:s');if(DB::table('attendance_entries')->where('organization_id',$organization->id)->where('employee_id',$e->id)->where('clock_in','>=',$time)->exists())throw ValidationException::withMessages(['attendance'=>'A later attendance entry already exists.']);$id=DB::table('attendance_entries')->insertGetId(['organization_id'=>$organization->id,'employee_id'=>$e->id,'clock_in'=>$time,'created_at'=>now(),'updated_at'=>now()]);$this->event($organization,$id,$r->user()->id,'clock_in',null,['clock_in'=>$time]);});return back()->with('status','Clocked in.');
 }
 public function clockOut(Request $r,Organization $organization) {
  $this->employee($r,$organization,'attendance.self.clock_out');
  DB::transaction(function()use($r,$organization){Organization::whereKey($organization->id)->lockForUpdate()->firstOrFail();$e=$this->employee($r,$organization,'attendance.self.clock_out');$entry=DB::table('attendance_entries')->where('organization_id',$organization->id)->where('employee_id',$e->id)->whereNull('clock_out')->lockForUpdate()->first();if(!$entry)throw ValidationException::withMessages(['attendance'=>'You have no open attendance entry.']);$time=now()->utc()->format('Y-m-d H:i:s');if($time<$entry->clock_in)throw ValidationException::withMessages(['attendance'=>'Clock-out cannot be earlier than clock-in.']);DB::table('attendance_entries')->where('id',$entry->id)->update(['clock_out'=>$time,'updated_at'=>now()]);$this->event($organization,$entry->id,$r->user()->id,'clock_out',null,['clock_out'=>$time]);});return back()->with('status','Clocked out.');
 }
 public function records(Request $r,Organization $organization) {
  abort_unless($r->user()->hasPermission('attendance.records.view',$organization),403);$ids=app(EmployeeAccess::class)->filter(Employee::query(),$r->user(),$organization,'attendance.records.view')->select('employees.id');
  $entries=DB::table('attendance_entries as a')->join('employees as e','e.id','=','a.employee_id')->where('a.organization_id',$organization->id)->where('e.organization_id',$organization->id)->whereIn('a.employee_id',$ids)->select('a.*','e.first_name','e.last_name')->orderByDesc('a.clock_in')->get();
  $employees=Employee::where('organization_id',$organization->id)->whereIn('id',$entries->pluck('employee_id'))->get()->keyBy('id');$events=collect();
  if($r->user()->hasPermission('attendance.history.view',$organization)) {$allowed=app(EmployeeAccess::class)->filter(Employee::query(),$r->user(),$organization,'attendance.history.view')->select('employees.id');$events=DB::table('attendance_events as ev')->join('attendance_entries as a','a.id','=','ev.attendance_entry_id')->where('ev.organization_id',$organization->id)->where('a.organization_id',$organization->id)->whereIn('a.employee_id',$allowed)->orderByDesc('ev.id')->limit(100)->select('ev.*')->get();}
  return view('attendance.records',compact('organization','entries','employees','events'));
 }
 public function correct(Request $r,Organization $organization,int $entry) {
  $data=$r->validate(['clock_in'=>'required|date_format:Y-m-d\TH:i','clock_out'=>'nullable|date_format:Y-m-d\TH:i|after_or_equal:clock_in','reason'=>'required|string|max:255']);
  DB::transaction(function()use($r,$organization,$entry,$data){Organization::whereKey($organization->id)->lockForUpdate()->firstOrFail();$row=DB::table('attendance_entries')->where('organization_id',$organization->id)->where('id',$entry)->lockForUpdate()->first();abort_unless($row,404);$employee=Employee::where('organization_id',$organization->id)->findOrFail($row->employee_id);abort_unless(app(EmployeeAccess::class)->allows($r->user(),$organization,'attendance.records.correct',$employee),403);$in=CarbonImmutable::createFromFormat('Y-m-d\TH:i',$data['clock_in'],'UTC')->format('Y-m-d H:i:s');$out=empty($data['clock_out'])?null:CarbonImmutable::createFromFormat('Y-m-d\TH:i',$data['clock_out'],'UTC')->format('Y-m-d H:i:s');if(!$out && DB::table('attendance_entries')->where('organization_id',$organization->id)->where('employee_id',$employee->id)->where('id','!=',$entry)->whereNull('clock_out')->exists())throw ValidationException::withMessages(['clock_out'=>'Another open entry already exists.']);$overlap=DB::table('attendance_entries')->where('organization_id',$organization->id)->where('employee_id',$employee->id)->where('id','!=',$entry)->where(function($q)use($in){$q->whereNull('clock_out')->orWhere('clock_out','>',$in);})->when($out,fn($q)=>$q->where('clock_in','<',$out))->exists();if($overlap)throw ValidationException::withMessages(['clock_in'=>'Attendance entries cannot overlap.']);DB::table('attendance_entries')->where('id',$entry)->update(['clock_in'=>$in,'clock_out'=>$out,'updated_at'=>now()]);$this->event($organization,$entry,$r->user()->id,'corrected',['clock_in'=>$row->clock_in,'clock_out'=>$row->clock_out],['clock_in'=>$in,'clock_out'=>$out],$data['reason']);});return back()->with('status','Attendance corrected.');
 }
 public function notifications(Request $r,Organization $organization) {$this->member($r,$organization,'daily.notifications.view');$notifications=DB::table('daily_notifications')->where('organization_id',$organization->id)->where('user_id',$r->user()->id)->orderByDesc('id')->get();return view('attendance.notifications',compact('organization','notifications'));}
 public function read(Request $r,Organization $organization,int $notification) {$this->member($r,$organization,'daily.notifications.read');$exists=DB::table('daily_notifications')->where('id',$notification)->where('organization_id',$organization->id)->where('user_id',$r->user()->id)->first();abort_unless($exists,404);DB::table('daily_notifications')->where('id',$notification)->where('organization_id',$organization->id)->where('user_id',$r->user()->id)->whereNull('read_at')->update(['read_at'=>now(),'updated_at'=>now()]);return back()->with('status','Notification marked read.');}
}
